
body{font-family:dejavusans,sans-serif;font-size:10pt;color:#303833}table{width:100%;border-collapse:collapse;table-layout:fixed;margin:0}.candidate-table th,.candidate-table td{border:1px solid #cfd6d2;padding:7px;vertical-align:middle;word-wrap:break-word}.candidate-table th{background:#f0f3f1;font-weight:bold}.candidate-table thead{display:table-header-group}tr{page-break-inside:avoid}.candidate-table .board-heading{background:white;text-align:left;border:0;padding:0 0 10px;font-weight:normal;line-height:1.35}.report-title{font-size:11pt;font-weight:bold;letter-spacing:.1px;color:#3e4d45;margin:0 0 6px}.report-meta{font-size:8.5pt;line-height:1.3;margin:0}.report-meta th,.report-meta td{border:1px solid #dce1de;padding:4px 6px;vertical-align:middle;text-align:left;word-wrap:break-word}.report-meta th{background:#f4f6f4;color:#536058;font-weight:bold}.report-meta td{background:white;color:#303833;font-weight:normal}.report-meta .post-name{font-weight:bold}.report-meta .commission{font-size:8pt;color:#536058}.candidate-table .center{text-align:center;vertical-align:middle}.candidate-table .name{text-align:left;vertical-align:middle}.notes{height:22px}.board-section{margin:0 0 28px}.controls{padding:15px;background:#f0f3f1;margin-bottom:20px}
@if(!$pdf)
@page{size:A4 portrait;margin:15mm 12mm 18mm;
@bottom-left{content:"BPSC CMO — Chairman’s Office";font-family:Arial,sans-serif;font-size:8pt;color:#59625d;border-top:1px solid #d7dfdb;vertical-align:top;padding-top:6px;width:65%}
@bottom-right{content:"Page " counter(page) " of " counter(pages);font-family:Arial,sans-serif;font-size:8pt;color:#59625d;border-top:1px solid #d7dfdb;vertical-align:top;text-align:right;padding-top:6px;width:35%}}
@media print{.controls{display:none}.board-section{margin:0;break-before:page;page-break-before:always}.board-section:first-of-type{break-before:auto;page-break-before:auto}thead{display:table-header-group}}
@endif
